// Package version: the factory's version and the runtime it pairs with.
//
// One product, one version (since v0.6.0): the generator, the runtime (runtime/, its own Go module
// github.com/MIERAI/api-factory/runtime) and the verification are released together. A release vX.Y.Z is two git tags
// on the same commit: vX.Y.Z (the factory) and runtime/vX.Y.Z (the runtime module, what `go get` resolves). A project
// generated by factory vX.Y.Z imports runtime vX.Y.Z; `factory upgrade` moves a project to the runtime paired with the
// factory that runs it. scripts/release.sh bumps every place that spells the version and creates the tags.
package version

// Factory: this factory's version (scripts/release.sh bump vX.Y.Z changes it, with every go.mod below).
const Factory = "v0.6.0"

// Runtime: the runtime version paired with this factory — always the same number.
const Runtime = Factory

// RuntimeModule: the runtime's module path (runtime/ in this repository). Generated code imports it.
const RuntimeModule = "github.com/MIERAI/api-factory/runtime"

// OldRuntimeModule: the runtime's module path up to v0.5.2 (its own repository MIERAI/api-factory-runtime, no longer
// developed). `factory upgrade` rewrites it to RuntimeModule.
const OldRuntimeModule = "github.com/MIERAI/api-factory-runtime"

// RuntimeTag: the git tag of the runtime module paired with this factory.
func RuntimeTag() string { return "runtime/" + Runtime }
